"""The street r2 numbers, read from `content/config/street_r2.tres` (generated by `netrun_art/gen_street_r2_config.py`).

The .tres is `name = <json>` lines, so the file is parsed here without Godot. `R` is keyed like the art-pass `RULES_R2`
(`"frontage.silhouette"` ...), so the ported rule code reads the same names."""
import json
import os
from typing import Any, Dict

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
PATH = os.path.join(ROOT, "content", "config", "street_r2.tres")
RULE_FIELDS = ("frontage_silhouette", "horizon_break", "materials_mix", "repetition_guard", "props_facade", "dressing_signs", "lod_signs",
               "streets_light", "foreground_street", "atmosphere_layers", "palette_districts")


def load(path: str = PATH) -> Dict[str, Any]:
    """All exported fields of the .tres as plain JSON values."""
    out: Dict[str, Any] = {}
    with open(path, encoding="utf-8") as f:
        past_header = False
        for line in f:
            line = line.rstrip("\n")
            if line == "[resource]":
                past_header = True
                continue
            if past_header and " = " in line and not line.startswith("script"):
                k, v = line.split(" = ", 1)
                out[k] = json.loads(v)
    return out


_C = load()
# the art-pass RULES_R2: "frontage.silhouette" -> block
R: Dict[str, Dict[str, Any]] = {name.replace("_", ".", 1): _C[name] for name in RULE_FIELDS}
SEEDS: Dict[str, int] = _C["seeds"]
WORDS: Dict[str, Any] = _C["words"]
SUBS = _C["subs"]
ADS: Dict[str, Any] = _C["ads"]
ONECITY: Dict[str, Any] = _C["onecity"]
KITS: Dict[str, Any] = _C["kits"]
SIGN_TEX: Dict[str, Any] = _C["sign_tex"]
